    from nipype.interfaces.base import isdefined

    d: dict[str, str] = {}
    if ktrans and isdefined(ktrans):
        d["ktrans"] = ktrans
    if ve and isdefined(ve):
        d["ve"] = ve
    if vp and isdefined(vp):
        d["vp"] = vp
    return d

